const acronyms = new Set(['aws', 'api', 'gcp', 'ai', 'ml', 'vpc', 'dns', 'sql', 'cdn', 'iam', 'ec2', 's3', 'eks', 'ecs', 'rds', 'sqs', 'sns', 'iot', 'vpn', 'cpu', 'gpu', 'http', 'https', 'tcp', 'udp', 'ip', 'vm', 'ssh', 'ssl', 'tls', 'os', 'ui', 'url', 'xml', 'json', 'css', 'html']);
const labelFor = name => name.split('-').map(word => acronyms.has(word) ? word.toUpperCase() : word[0]?.toUpperCase() + word.slice(1)).join(' ');
// Eraser documents this legacy spelling, but only its hyphenated asset currently exists.
export const ERASER_ICON_ALIASES = Object.freeze({ 'eraser.io': 'eraser-io' });
export const ERASER_ICON_CATEGORIES = Object.freeze(groups.map(({ category, names }) => Object.freeze({ name: category, count: names.length })));
export const ERASER_ICONS = Object.freeze(groups.flatMap(({ category, names }) => names.map(name => Object.freeze({
  id: 'eraser:' + name, label: labelFor(name), category, role: 'eraser-icon', color: '#a9b4c2',
  iconName: name, monochrome: category === 'General icons', description: category + ' · ' + name,
}))));
const iconNames = new Set(ERASER_ICONS.map(icon => icon.iconName));
export function isEraserIconName(name) { return typeof name === 'string' && iconNames.has(name); }
export function eraserIconAssetName(name) { if (!isEraserIconName(name)) throw new TypeError('Unknown Eraser icon'); return ERASER_ICON_ALIASES[name] || name; }
export function eraserIconUrl(name) { return ERASER_ICON_CATALOG_METADATA.assetBaseUrl + encodeURIComponent(eraserIconAssetName(name)) + '.svg'; }
